<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import InputError from '@/Components/InputError.vue';
import InvitationPreviewRenderer from '@/Components/InvitationPreviewRenderer.vue';
import PageHeader from '@/Components/UI/PageHeader.vue';
import { templatePreviewUrl } from '@/Support/templatePreviews';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, onMounted, ref, watch } from 'vue';

const props = defineProps<{ event:any; step:number; templates:any[]; overrides:any; resolvedSettings:any; previewInvitation:any; workflow:any; timezones:string[] }>();
const dateValue = (value:any) => value ? value.slice(0, 10) : '';
const timeValue = (value:any) => value ? value.slice(0, 5) : '';
const previewing = ref<any | null>(null);
const carouselIndex = ref(0);
const launchTypes = [{ value: 'wedding', label: 'Wedding' }, { value: 'engagement', label: 'Engagement' }];
const design = useForm({ event_type: props.event.event_type || '', template_id: props.event.template_id || '', settings: { palette_key: props.overrides.palette_key || '', font_pair_key: props.overrides.font_pair_key || '' } });
const information = useForm({ title: props.event.title || '', host_name: props.event.host_name || '', second_host_name: props.event.second_host_name || '', description: props.event.description || '', main_date: dateValue(props.event.main_date), start_time: timeValue(props.event.start_time), end_time: timeValue(props.event.end_time), event_timezone: props.event.event_timezone || '', venue: props.event.venue || '', address: props.event.address || '', location_url: props.event.location_url || '', rsvp_deadline: dateValue(props.event.rsvp_deadline) });
const compatibleTemplates = computed(() => design.event_type ? props.templates.filter((template:any) => !template.supported_event_types?.length || template.supported_event_types.includes(design.event_type)) : []);
const currentTemplate = computed(() => compatibleTemplates.value[carouselIndex.value] || null);
const previewInvitation = computed(() => ({ ...props.previewInvitation, template: currentTemplate.value ? { name: currentTemplate.value.name, component_key: currentTemplate.value.component_key } : props.previewInvitation.template, settings: props.resolvedSettings }));
const previewFor = computed(() => previewing.value ? { ...previewInvitation.value, template: { name: previewing.value.name, component_key: previewing.value.component_key }, settings: props.resolvedSettings } : previewInvitation.value);
const completion = computed(() => [information.title, information.host_name, information.main_date, information.start_time, information.event_timezone].filter(Boolean).length);
const nextDay = computed(() => Boolean(information.start_time && information.end_time && information.end_time < information.start_time));
const previewAsset = (componentKey: string) => templatePreviewUrl(componentKey) ?? undefined;
const selectType = (type: string) => { design.event_type = type; design.template_id = ''; carouselIndex.value = 0; };
const previousTemplate = () => { if (compatibleTemplates.value.length) carouselIndex.value = (carouselIndex.value - 1 + compatibleTemplates.value.length) % compatibleTemplates.value.length; };
const nextTemplate = () => { if (compatibleTemplates.value.length) carouselIndex.value = (carouselIndex.value + 1) % compatibleTemplates.value.length; };
const chooseCurrentTemplate = () => { if (currentTemplate.value) design.template_id = currentTemplate.value.id; };
const saveDesign = () => { chooseCurrentTemplate(); design.transform((data:any) => ({ event_type: data.event_type, template_id: data.template_id, settings: { palette_key: data.settings.palette_key || null, font_pair_key: data.settings.font_pair_key || null } })).patch(route('events.setup.save', { event: props.event.id, step: 'design' })); };
const saveInformation = () => information.patch(route('events.setup.save', { event: props.event.id, step: 'information' }));
const backToDesign = () => router.get(route('events.setup', { event: props.event.id, step: 1 }));
const exitUrl = route('dashboard');
onMounted(() => {
    const detected = Intl.DateTimeFormat().resolvedOptions().timeZone;
    if (!information.main_date && (!information.event_timezone || information.event_timezone === 'UTC') && detected && props.timezones.includes(detected)) information.event_timezone = detected;
});
watch(() => design.event_type, () => { carouselIndex.value = 0; });
</script>

<template>
    <Head title="Create Your Invitation" />
    <AuthenticatedLayout>
        <template #header><PageHeader :title="step === 1 ? 'Choose Your Invitation Design' : 'Enter Your Information'" :eyebrow="step === 1 ? 'Step 1 of 3' : 'Step 2 of 3'" :subtitle="step === 1 ? 'Select what you are celebrating, then choose a design.' : 'Add the essential information before the final personalization step.'"><template #actions><Link :href="exitUrl" class="fe-btn fe-btn-secondary">Exit</Link></template></PageHeader></template>
        <main class="fe-page fe-page-wide space-y-6">
            <ol class="grid gap-2 sm:grid-cols-3" aria-label="Invitation creation progress"><li class="rounded-xl border p-3" :class="step === 1 ? 'border-[color:var(--fe-primary)] bg-[color:var(--fe-surface-elevated)]' : 'border-[color:var(--fe-border)]'"><span class="text-xs font-bold uppercase tracking-[.15em]">1 · Type &amp; Design</span><p class="mt-1 text-sm">Choose your style</p></li><li class="rounded-xl border p-3" :class="step === 2 ? 'border-[color:var(--fe-primary)] bg-[color:var(--fe-surface-elevated)]' : 'border-[color:var(--fe-border)]'"><span class="text-xs font-bold uppercase tracking-[.15em]">2 · Information</span><p class="mt-1 text-sm">Add essential details</p></li><li class="rounded-xl border p-3 border-[color:var(--fe-border)]"><span class="text-xs font-bold uppercase tracking-[.15em]">3 · Personalize</span><p class="mt-1 text-sm">Finish your invitation</p></li></ol>
            <form v-if="step === 1" class="space-y-6" @submit.prevent="saveDesign"><section class="rounded-3xl border border-[color:var(--fe-border)] bg-[color:var(--fe-surface)] p-5 shadow-sm sm:p-8"><div class="max-w-2xl"><p class="fe-page-eyebrow">Your celebration</p><h2 class="fe-section-title mt-1">What are you celebrating?</h2><div class="mt-4 flex flex-wrap gap-3"><button v-for="type in launchTypes" :key="type.value" type="button" class="rounded-xl border px-5 py-3 font-semibold" :class="design.event_type === type.value ? 'border-[color:var(--fe-primary)] bg-[color:var(--fe-surface-elevated)]' : 'border-[color:var(--fe-border)]'" @click="selectType(type.value)">{{ type.label }}</button></div><InputError :message="design.errors.event_type" class="mt-2" /><p v-if="design.event_type" class="fe-section-copy mt-6">Personalize your wording, photos, and invitation details in the next steps.</p></div><section v-if="currentTemplate" class="mx-auto mt-8 max-w-4xl"><div class="grid items-center gap-5 md:grid-cols-[auto_minmax(0,1fr)_auto]"><button type="button" class="fe-btn fe-btn-secondary justify-self-center" aria-label="Previous design" @click="previousTemplate">←</button><article class="overflow-hidden rounded-3xl border border-[color:var(--fe-border)] bg-[color:var(--fe-surface-elevated)] p-4 shadow-sm"><img v-if="previewAsset(currentTemplate.component_key)" :src="previewAsset(currentTemplate.component_key)" :alt="`${currentTemplate.name} invitation preview`" class="mx-auto aspect-[9/16] max-h-[38rem] w-full max-w-sm rounded-2xl object-cover" /><div class="mx-auto mt-4 max-w-sm"><p class="font-semibold">{{ currentTemplate.name }}</p><p class="mt-1 text-sm text-[color:var(--fe-text-secondary)]">{{ currentTemplate.description }}</p><div class="mt-4 flex flex-wrap gap-3"><button type="button" class="fe-btn fe-btn-secondary" @click="previewing = currentTemplate">Preview Full Design</button><span v-if="Number(design.template_id) === currentTemplate.id" class="self-center text-sm font-semibold text-[color:var(--fe-success)]">Selected</span></div></div></article><button type="button" class="fe-btn fe-btn-secondary justify-self-center" aria-label="Next design" @click="nextTemplate">→</button></div><div class="mt-4 flex justify-center gap-2" aria-label="Design position"><button v-for="(_, index) in compatibleTemplates" :key="index" type="button" class="h-2.5 w-2.5 rounded-full" :class="carouselIndex === index ? 'bg-[color:var(--fe-primary)]' : 'bg-[color:var(--fe-border-strong)]'" :aria-label="`Show design ${index + 1}`" @click="carouselIndex = index"></button></div></section><p v-else-if="design.event_type" class="mt-8 text-sm text-[color:var(--fe-warning)]">No approved designs are available for this invitation type.</p><p v-else class="mt-8 text-sm text-[color:var(--fe-text-secondary)]">Choose Wedding or Engagement to see compatible designs.</p><InputError :message="design.errors.template_id" class="mt-3" /><div class="mt-7 flex justify-end"><button :disabled="!currentTemplate || design.processing || !workflow.can_manage" class="fe-btn fe-btn-primary">{{ design.processing ? 'Saving...' : 'Use This Design' }}</button></div></section></form>
            <form v-else class="mx-auto max-w-3xl rounded-3xl border border-[color:var(--fe-border)] bg-[color:var(--fe-surface)] p-5 shadow-sm sm:p-8" @submit.prevent="saveInformation"><fieldset :disabled="!workflow.can_manage" class="space-y-6"><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="fe-page-eyebrow">Essential invitation details</p><h2 class="fe-section-title mt-1">Give guests the information they need.</h2></div><p class="rounded-full bg-[color:var(--fe-surface-elevated)] px-3 py-1 text-sm font-semibold">{{ completion }} of 5 essentials ready</p></div><div class="grid gap-4 sm:grid-cols-2"><label>Invitation title<input v-model="information.title" class="mt-1 w-full" /><InputError :message="information.errors.title" /></label><label>First host<input v-model="information.host_name" class="mt-1 w-full" /><InputError :message="information.errors.host_name" /></label><label>Second host <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.second_host_name" class="mt-1 w-full" /></label><label>Event date<input v-model="information.main_date" type="date" class="mt-1 w-full" /><InputError :message="information.errors.main_date" /></label><label>RSVP deadline <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.rsvp_deadline" type="date" class="mt-1 w-full" /><InputError :message="information.errors.rsvp_deadline" /></label><label>Start time<input v-model="information.start_time" type="time" class="mt-1 w-full" /><InputError :message="information.errors.start_time" /></label><label>End time <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.end_time" type="time" class="mt-1 w-full" /><p v-if="nextDay" class="mt-1 text-xs font-medium text-[color:var(--fe-accent)]">Ends the next day</p><InputError :message="information.errors.end_time" /></label><label class="sm:col-span-2">Timezone<select v-model="information.event_timezone" class="mt-1 w-full"><option value="">Select timezone</option><option v-for="timezone in timezones" :key="timezone" :value="timezone">{{ timezone }}</option></select><InputError :message="information.errors.event_timezone" /></label><label>Venue <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.venue" class="mt-1 w-full" /></label><label>Address <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.address" class="mt-1 w-full" /></label><label class="sm:col-span-2">Location URL <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.location_url" type="url" class="mt-1 w-full" /><InputError :message="information.errors.location_url" /></label><label class="sm:col-span-2">Invitation wording <span class="text-[color:var(--fe-text-muted)]">(optional)</span><textarea v-model="information.description" rows="4" class="mt-1 w-full" /></label></div><div class="flex flex-wrap items-center justify-between gap-3 border-t border-[color:var(--fe-border)] pt-6"><button type="button" class="fe-btn fe-btn-secondary" @click="backToDesign">Previous</button><button :disabled="information.processing" class="fe-btn fe-btn-primary">{{ information.processing ? 'Saving...' : 'Continue to personalize' }}</button></div></fieldset></form>
        </main>
        <div v-if="previewing" class="fixed inset-0 z-50 grid place-items-center bg-slate-950/60 p-4" role="dialog" aria-modal="true" aria-label="Template preview"><div class="max-h-[92dvh] w-full max-w-xl overflow-auto rounded-3xl bg-white p-4 shadow-2xl"><div class="mb-3 flex items-center justify-between"><p class="font-semibold">{{ previewing.name }} preview</p><button type="button" class="fe-btn fe-btn-secondary" @click="previewing = null">Close</button></div><iframe v-if="previewing.demo_url" :src="previewing.demo_url" :title="`${previewing.name} demo`" class="h-[75dvh] w-full border-0" /><InvitationPreviewRenderer v-else :invitation="previewFor" /></div></div>
    </AuthenticatedLayout>
</template>
